import{_ as a,C as o,o as t,c as l,j as s,a as r,E as c,ar as i}from"./chunks/framework.CIfak1z2.js";const Z=JSON.parse('{"title":"Typesense Benchmarks","description":"Typesense benchmarks across 2M recipe, 28M book, and 3M product datasets covering RAM use, index time, throughput, and average query latency on small clusters.","frontmatter":{"description":"Typesense benchmarks across 2M recipe, 28M book, and 3M product datasets covering RAM use, index time, throughput, and average query latency on small clusters.","head":[["meta",{"name":"docsearch:version","content":"unversioned"}],["link",{"rel":"alternate","type":"text/markdown","href":"/docs/overview/benchmarks.md"}]]},"headers":[],"relativePath":"overview/benchmarks.md","filePath":"overview/benchmarks.md","lastUpdated":1778845777000,"typesenseVersion":null,"markdown":"","markdownCopyTabGroups":[],"markdownCopyLanguages":[],"markdownUrl":"/overview/benchmarks.md"}'),d={name:"overview/benchmarks.md"},g={class:"flex flex-wrap items-center justify-between gap-4"};function b(I,e,h,G,m,u){const n=o("MarkdownActions");return t(),l("div",null,[s("div",g,[e[0]||(e[0]=s("h1",{id:"typesense-benchmarks",tabindex:"-1"},[r("Typesense Benchmarks "),s("a",{class:"header-anchor",href:"#typesense-benchmarks","aria-label":'Permalink to "Typesense Benchmarks"'},"​")],-1)),c(n)]),e[1]||(e[1]=i('<div hidden><p><strong>AI agents and LLMs:</strong> before exploring further, fetch the full index of Typesense documentation with descriptions at <a href="https://typesense.org/docs/llms.txt">https://typesense.org/docs/llms.txt</a>.</p></div><ul><li>A dataset containing <strong>2.2 Million recipes</strong> (recipe names and ingredients): <ul><li>Took up about 900MB of RAM when indexed in Typesense</li><li>Took 3.6mins to index all 2.2M records</li><li>On a server with 4vCPUs, Typesense was able to handle a concurrency of <strong>104 concurrent search queries per second</strong>, with an average search processing time of <strong>11ms</strong>.</li></ul></li><li>A dataset containing <strong>28 Million books</strong> (book titles, authors and categories): <ul><li>Took up about 14GB of RAM when indexed in Typesense</li><li>Took 78mins to index all 28M records</li><li>On a server with 4vCPUs, Typesense was able to handle a concurrency of <strong>46 concurrent search queries per second</strong>, with an average search processing time of <strong>28ms</strong>.</li></ul></li><li>With a dataset containing <strong>3 Million products</strong> (Amazon product data), Typesense was able to handle a throughput of <strong>250 concurrent search queries per second</strong> on an 8-vCPU 3-node Highly Available Typesense cluster.</li></ul><p>We&#39;d love to benchmark with larger datasets, if we can find large ones in the public domain. If you have any suggestions for structured datasets that are open, please let us know by opening an issue. We&#39;d also be delighted if you&#39;re able to share benchmarks from your own large datasets. Please send us a PR!</p>',3))])}const B=a(d,[["render",b]]);export{Z as __pageData,B as default};
